def footer(canvas,doc):
    canvas.saveState(); canvas.setFont("Helvetica",7); canvas.setFillColor(colors.grey)
    canvas.drawCentredString(A4[0]/2,18,f"Padma Bridge ML Project | Page {doc.page}"); canvas.restoreState()

def table(data,widths=None,font=7.2,repeat=1):
    data=[[Paragraph(str(x),styles["Small"]) for x in row] for row in data]
    t=Table(data,colWidths=widths,repeatRows=repeat,hAlign="CENTER")
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),BLUE),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,GREY]),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#9aa7b2")),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("LEFTPADDING",(0,0),(-1,-1),4),("RIGHTPADDING",(0,0),(-1,-1),4),("TOPPADDING",(0,0),(-1,-1),4),("BOTTOMPADDING",(0,0),(-1,-1),4)]));return t

def p(txt,style="BodyJ"): return Paragraph(txt,styles[style])
def bullets(items): return [Paragraph("• "+x,styles["BodyJ"]) for x in items]
def fig(path,caption,w=6.8*inch,h=3.5*inch): return [Image(str(path),width=w,height=h),p(caption,"Caption")]
