def doc(path): return SimpleDocTemplate(str(path),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=38,bottomMargin=32,title=path.stem,author="CSE 4112 Group B2")

def make_directional_figs(root,direct,best):
    f=root/"outputs"/"figures";f.mkdir(exist_ok=True,parents=True)
    q=direct[(direct.strategy=="Direct") & (~direct.model.str.contains("Persistence|Seasonal"))].copy(); q["display_mae"]=np.where(q.target.str.contains("cash"),q.MAE/1e6,q.MAE)
    fig,axs=plt.subplots(2,2,figsize=(10,7));
    for ax,(target,g) in zip(axs.ravel(),q.groupby("target")):
        g=g.sort_values("display_mae");ax.barh(g.model,g.display_mae,color="#4472c4");ax.set_title(target.replace("_"," ").title());ax.set_xlabel("MAE (million BDT)" if "cash" in target else "MAE (vehicles)")
    fig.tight_layout();fig.savefig(f/"model_mae_comparison.png",dpi=180,bbox_inches="tight");plt.close(fig)
    s=direct[direct.strategy=="Total-and-share"].groupby(["target","model"],as_index=False).MAE.mean(); s["display_mae"]=np.where(s.target.str.contains("cash"),s.MAE/1e6,s.MAE)
    fig,axs=plt.subplots(1,2,figsize=(10,4));
    for ax,kind in zip(axs,["traffic","cash"]):
        a=q[q.target.str.contains(kind)].groupby("model").display_mae.mean();b=s[s.target.str.contains(kind)].groupby("model").display_mae.mean();z=pd.concat([a.rename("Direct"),b.rename("Total-and-share")],axis=1).sort_values("Direct");z.plot.bar(ax=ax,color=["#4472c4","#70ad47"]);ax.set_title(kind.title()+" strategy comparison");ax.set_ylabel("Mean side MAE"+(" (million BDT)" if kind=="cash" else " (vehicles)"));ax.tick_params(axis="x",rotation=35)
    fig.tight_layout();fig.savefig(f/"strategy_comparison.png",dpi=180,bbox_inches="tight");plt.close(fig)
    return f

def directional_report():
    r=BASE/"directional_forecasting_ashique";out=r/"outputs";m=pd.read_csv(out/"directional_test_metrics.csv");best=pd.read_csv(out/"best_directional_models.csv");summ=json.loads((out/"run_summary.json").read_text());ev=pd.read_csv(out/"eid_direction_profile.csv");f=make_directional_figs(r,m,best)
