def make_multi_figs(r,m,pred,best):
    f=r/"outputs"/"figures";f.mkdir(parents=True,exist_ok=True)
    q=m[(m.horizon_band=="all") & (~m.model.str.contains("Persistence|Seasonal"))].copy();q["v"]=np.where(q.target.eq("toll"),q.MAE/1e6,q.MAE)
    fig,axs=plt.subplots(1,2,figsize=(10,4));
    for ax,(target,g) in zip(axs,q.groupby("target")):
        g=g.sort_values("v");ax.bar(g.model,g.v,color="#4472c4");ax.tick_params(axis="x",rotation=30);ax.set_title(target.title()+" overall MAE");ax.set_ylabel("million BDT" if target=="toll" else "vehicles")
    fig.tight_layout();fig.savefig(f/"overall_model_comparison.png",dpi=180,bbox_inches="tight");plt.close(fig)
    fig,axs=plt.subplots(3,2,figsize=(11,9));
    for i,h in enumerate([1,7,30]):
      q=pred[pred.horizon==h].sort_values("target_date")
      for j,target in enumerate(["traffic","toll"]):
        name=best.loc[best.target==target,"model"].iloc[0];ax=axs[i,j];ax.plot(pd.to_datetime(q.target_date),q[target+"_actual"] if target+"_actual" in q else np.nan,label="Actual");ax.plot(pd.to_datetime(q.target_date),q[target+"_"+name],label=name,lw=1);ax.set_title(f"{target.title()} — horizon {h}");ax.legend(fontsize=7)
    fig.tight_layout();fig.savefig(f/"predictions_by_horizon.png",dpi=180,bbox_inches="tight");plt.close(fig)
    return f

def multihorizon_report():
    r=BASE/"multihorizon_forecasting_ashique";out=r/"outputs";m=pd.read_csv(out/"multihorizon_test_metrics.csv");best=pd.read_csv(out/"best_models.csv");pred=pd.read_csv(out/"multihorizon_test_predictions.csv");agg=pd.read_csv(out/"aggregate_period_metrics.csv");summ=json.loads((out/"run_summary.json").read_text())
    # Add actual columns from the underlying expanded dataset by joining source target dates.
    raw=pd.read_csv(BASE/"padma_bridge_ml_complete"/"data"/"raw"/"padma_toll_report_with_holidays_weather.csv");raw["target_date"]=pd.to_datetime(raw.Date,dayfirst=True).dt.strftime("%Y-%m-%d");raw["traffic_actual"]=pd.to_numeric(raw.Total_Traffic.astype(str).str.replace(",",""),errors="coerce");raw["toll_actual"]=pd.to_numeric(raw.Total_Cash.astype(str).str.replace(",",""),errors="coerce");pred=pred.merge(raw[["target_date","traffic_actual","toll_actual"]],on="target_date",how="left");f=make_multi_figs(r,m,pred,best)
    story=cover("Multi-Horizon Traffic and Toll Revenue Forecasting for the Padma Bridge","Next-day, weekly and monthly forecasting with horizon-aware models","Ashique portion: multi-horizon forecasting update")
    story += [p("Executive summary","H1x"),p(f"This project extends one-day Padma Bridge forecasting to a global direct system covering horizons 1–30. Historical origin dates were expanded into <b>{summ['expanded_samples']:,}</b> origin–horizon examples with <b>{summ['features']}</b> predictors. All samples from one origin remained in the same chronological partition, and no observed bridge value after the origin was used."),p("Across the complete held-out horizon set, XGBoost was the best traffic model with MAE 2,415 vehicles and MAPE 14.21%. CatBoost was the best toll model with MAE BDT 2.580 million and MAPE 14.16%. Performance declines with horizon, confirming the increased uncertainty of longer-range prediction."),p("Main finding","H2x"),p("A single horizon-aware model can learn next-day, weekly and monthly relationships while preserving origin-date integrity. Tree boosting is more reliable than persistence at longer horizons, although rare Eid periods remain substantially harder."),p("Work completed","H2x")]+bullets(["Generated horizon-labelled targets from 1 to 30 days.","Created origin-safe traffic/toll history and target-date calendar, event and weather inputs.","Trained and saved Random Forest, XGBoost, CatBoost and Residual MLP models for both targets.","Calculated horizon-band, holiday, Eid, weekly-total and 30-day-total metrics."])+[PageBreak()]
    story += [p("1. Introduction","H1x"),p("A one-day forecast supports immediate operations, but staffing, maintenance, revenue planning and event preparation require a longer view. Simply applying a one-day model repeatedly would introduce unknown future lags and compound errors. The implemented global-direct approach instead gives every training sample an explicit forecast horizon and predicts each future date directly from a common forecast origin."),p("1.1 Objectives","H2x")]+bullets(["Preserve next-day performance as a baseline.","Produce daily total traffic and toll predictions for horizons 1–30.","Compare ensemble and neural models consistently across horizons.","Measure daily, weekly-total, monthly-total, holiday and Eid errors.","Document future-weather uncertainty and avoid origin leakage."])+[p("1.2 Forecasting relationship","H2x"),p("History available on origin date t + target-date calendar/weather + horizon h → bridge total on date t+h."),PageBreak()]
    story += [p("2. Data construction","H1x"),table([["Item","Value"],["Raw Padma rows","1,520 daily records"],["Expanded complete samples",f"{summ['expanded_samples']:,}"],["Forecast horizons","1 through 30 days"],["Predictors",str(summ["features"])],["Test origins",str(summ['origin_split']['test_origins'])],["Test-origin range",f"{summ['origin_split']['test_start']} – {summ['origin_split']['test_end']}"]],[2.0*inch,4.5*inch]),p("2.1 Origin expansion","H2x"),p("For every eligible origin date, 30 supervised examples were created. The predictors describe the same origin history but each row receives a different horizon and target date. Traffic and toll targets are shifted backward by h days so that they refer to the correct future observation."),p("2.2 Target-date information","H2x"),p("Weekday, month, day-of-year, weekend, holiday, Eid proximity and rail-operation status are known from the target date. Historical target-date weather is used in the backtest to represent supplied forecast weather. For actual 8–30 day deployment, unavailable weather should be replaced with a genuine forecast or seasonal climatology and accompanied by a larger uncertainty statement."),PageBreak()]
    story += [p("3. Leakage prevention and chronological split","H1x"),p("Every example is assigned to train/development or test according to its forecast-origin date, not its target date. Thus, the 30 rows originating on one date cannot be split across partitions. Observed bridge-history columns stop at the origin date; later traffic and toll values are targets only."),p("This grouping rule is essential. Splitting expanded rows randomly would allow nearly identical samples from one origin to appear in both training and test data, producing an unrealistically optimistic score."),p("3.1 Features","H2x"),table([["Family","Variables"],["Origin history","Traffic/toll lags 0–28 and rolling mean/standard deviation"],["Target calendar","Cyclic weekday, month and annual encodings; weekend"],["Events","Public holiday, Eid and distance to nearest Eid"],["External","Target weather and railway-operation indicator"],["Horizon","Integer forecast_horizon from 1 to 30"]],[1.55*inch,4.95*inch]),p("3.2 Models","H2x"),table([["Model","Role"],["Persistence","Latest observed level for all future dates"],["Seasonal baseline","Most recent known value matching target weekday"],["Random Forest","Nonlinear bagged trees"],["XGBoost","Regularized gradient boosting"],["CatBoost","Alternative boosting model"],["Residual MLP","Predicts change relative to the origin value"]],[1.55*inch,4.95*inch]),PageBreak()]
    story += [p("4. Overall forecasting results","H1x"),table([["Target","Best model","MAE","RMSE","MAPE","R-squared"]]+[[x.target.title(),x.model,f"{x.MAE:,.0f}",f"{x.RMSE:,.0f}",f"{x.MAPE:.2f}%",f"{x.R2:.3f}"] for _,x in best.iterrows()],[1.0*inch,1.1*inch,1.0*inch,1.0*inch,.75*inch,.75*inch]),p("Interpretation","H2x"),p("XGBoost explains about half of the variation in 1–30 day traffic targets and provides the lowest traffic MAE. CatBoost provides the lowest toll MAE, while overall toll R-squared is lower at 0.314. This is expected because toll revenue combines traffic variation with changes in vehicle composition and revenue per vehicle, neither of which is directly forecast at long horizons.")]+fig(f/"overall_model_comparison.png","Figure 1. Overall held-out MAE across the four trained model families.",6.8*inch,2.8*inch)+[PageBreak()]
    story += [p("5. Accuracy by forecast horizon","H1x"),p("The horizon bands separate immediate prediction (day 1), short-range planning (days 2–7) and longer-range planning (days 8–30). Errors increase because recent observations become less informative and future events/weather are less certain.")]+fig(f/"error_by_horizon.png","Figure 2. Traffic and toll MAPE by horizon band for every trained model.",6.8*inch,2.85*inch)
    bands=m[(~m.model.str.contains("Persistence|Seasonal")) & m.horizon_band.isin(["1 day","2-7 days","8-30 days"])]
